begin;
create or replace function public.network_protect_evidence_immutability() returns trigger language plpgsql security invoker set search_path=pg_catalog, public, extensions, pg_temp as $$ begin if tg_op='DELETE' then raise exception 'network oracle evidence is immutable'; end if; if new.oracle_id<>old.oracle_id or new.settlement_batch_id is distinct from old.settlement_batch_id or new.route_id is distinct from old.route_id or new.manifest_id is distinct from old.manifest_id or new.evidence_type<>old.evidence_type or new.payload<>old.payload or new.payload_hash<>old.payload_hash or new.signature<>old.signature or new.signature_encoding<>old.signature_encoding or new.issued_at<>old.issued_at or new.expires_at<>old.expires_at or new.nonce<>old.nonce or new.created_at<>old.created_at then raise exception 'network oracle evidence immutable envelope violation'; end if; return new; end; $$;
create or replace function public.network_protect_gate_requirement_immutability() returns trigger language plpgsql security invoker set search_path=pg_catalog, public, extensions, pg_temp as $$ declare v_state text; begin select state into v_state from public.network_financial_finality_gates where gate_id=coalesce(old.gate_id,new.gate_id); if tg_op='DELETE' and v_state='pending' then return old; end if; if tg_op='DELETE' then raise exception 'financial finality requirements are immutable after gate activation'; end if; if new.gate_id<>old.gate_id or new.evidence_type<>old.evidence_type or new.required_count<>old.required_count then raise exception 'financial finality requirement immutable'; end if; return new; end; $$;
commit;